pub type Vector3D = (Float64, Float64, Float64);

fn magnitude(v: &Vector3D) -> Float64 {
  return math.sqrt(v.0 * v.0 + v.1 * v.1 + v.2 * v.2);
}

fn main() -> Int {
  let v = Vector3D(3.0, 4.0, 0.0);
  let m = magnitude(&v);
  return m as Int;
}
